// Object3D imported only for the JSDoc type below; project lint config
// permits type-only imports.
import {Object3D, Quaternion, Raycaster, Vector3} from 'three'
import {worldToLatLngAlt} from '../coords.js'


// Reused across calls to avoid per-frame allocations.
const _raycaster = new Raycaster
const _itemVec = new Vector3
const _mouseVec = new Vector3
const _rayOrigin = new Vector3
const _rayDir = new Vector3
const _starsQuat = new Quaternion

// Reject picks whose closest hit is farther than this many screen pixels.
export const MAX_PICK_PX = 100


/**
 * Find the star nearest to the mouse cursor and call pickCb with it.
 *
 * @param {object} ui
 * @param {MouseEvent} e
 * @param {object} tree  Spatial index built from the index's coords
 * @param {object} stars Stars scene object (has .catalog, .matrixWorld)
 * @param {Function} pickCb Called with {star, x, y, z} in catalog coords
 * @param {object} [index] The stars' pick index (Stars.pickIndex: the loaded
 *   stars' positions and HIP numbers, the tree's source)
 */
export function queryPoints(ui, e, tree, stars, pickCb, index = stars.pickIndex?.() ?? stars.geom) {
  const el = ui.renderer.domElement
  const mouse = {
    x: ((e.clientX / el.clientWidth) * 2) - 1,
    y: ((e.clientY / el.clientHeight) * -2) + 1,
  }
  _raycaster.setFromCamera(mouse, ui.camera)
  const ray = _raycaster.ray

  // Stars are stored in catalog coordinates (J2000), and drawn through the
  // stars' matrixWorld: the StellarFrame's precession to the date, then the
  // WorldGroup's rebase.  Bring the ray into catalog space instead of
  // rebuilding the spatial index: origin by the inverse matrixWorld,
  // direction by the inverse rotation.
  stars.updateWorldMatrix(true, false)
  _rayOrigin.copy(ray.origin)
  stars.worldToLocal(_rayOrigin)
  stars.getWorldQuaternion(_starsQuat).invert()
  _rayDir.copy(ray.direction).applyQuaternion(_starsQuat)

  const items = tree.intersectRay(_rayOrigin, _rayDir)
  if (items.length > 0) {
    mark(ui, items, mouse, stars, pickCb, index)
  }
}


/**
 * @param {object} ui
 * @param {Array} items  Flat array of indices from tree.intersectRay; each
 *                       element is a flat index into index.coords (i.e.
 *                       a multiple of 3, one entry per matching star).
 * @param {{x,y}} mouse  NDC mouse position
 * @param {object} stars
 * @param {Function} pickCb
 * @param {object} index Stars.pickIndex
 */
function mark(ui, items, mouse, stars, pickCb, index) {
  const coords = index.coords
  const el = ui.renderer.domElement
  const clientW = el.clientWidth
  const clientH = el.clientHeight

  _mouseVec.set(mouse.x, mouse.y, 0)

  let minDist = Infinity
  let closestNdx = -1
  let minX = 0; let minY = 0; let minZ = 0

  // items is one flat index per matching star (not triplets) — step by 1.
  for (let i = 0; i < items.length; i++) {
    const ndx = items[i]
    const x = coords[ndx]; const y = coords[ndx + 1]; const z = coords[ndx + 2]
    // Project world-space position into NDC for screen-distance comparison.
    _itemVec.set(x, y, z).applyMatrix4(stars.matrixWorld)
    _itemVec.project(ui.camera)
    // Compute screen distance in pixels (ignore z/depth).
    const pxDx = (_itemVec.x - mouse.x) * clientW / 2
    const pxDy = (_itemVec.y - mouse.y) * clientH / 2
    const dist = (pxDx * pxDx) + (pxDy * pxDy) // squared pixels — cheaper than sqrt
    if (dist < minDist) {
      minDist = dist
      closestNdx = ndx
      minX = x; minY = y; minZ = z
    }
  }

  if (closestNdx < 0 || minDist > MAX_PICK_PX * MAX_PICK_PX) {
    return
  }

  const hipId = index.idsByNdx[closestNdx / 3]
  const star = stars.catalog.starByHip.get(hipId)
  pickCb({star, x: minX, y: minY, z: minZ})
}


// Reusable temps for pickSurfaceLatLng.
const _surfL = new Vector3()
const _surfBodyCenter = new Vector3()
const _surfBodyQuat = new Quaternion()
const _surfHit = new Vector3()


/**
 * Ray-sphere intersect a pointer event against a body's implicit surface
 * sphere (center = body world position, radius = `props.radius.scalar`) and
 * return the hit point as geographic coordinates in the body-fixed frame.
 *
 * No mesh raycasting: surface meshes are LOD-swapped and may not be the
 * geometry actually rendered at a given camera distance (the far-LOD is a
 * Point sprite, the very-far LOD is invisible).  The implicit sphere is
 * always available — only `props.radius.scalar` is needed — and matches
 * what the user sees for any LOD level since all bodies render as spheres.
 *
 * Returns null when the ray misses, when the body has no radius, or when
 * the only intersections are behind the camera.
 *
 * @param {object} ui  ThreeUI; uses .renderer, .camera
 * @param {{clientX:number, clientY:number}} e  Pointer event
 * @param {Object3D} body  Body Object3D with `.props.radius.scalar`
 * @returns {?{lat: number, lng: number, alt: number}}
 */
export function pickSurfaceLatLng(ui, e, body) {
  const radius = body?.props?.radius?.scalar
  if (!radius) {
    return null
  }

  const el = ui.renderer.domElement
  const mouse = {
    x: ((e.clientX / el.clientWidth) * 2) - 1,
    y: ((e.clientY / el.clientHeight) * -2) + 1,
  }
  _raycaster.setFromCamera(mouse, ui.camera)
  const ray = _raycaster.ray

  body.updateMatrixWorld()
  body.getWorldPosition(_surfBodyCenter)
  body.getWorldQuaternion(_surfBodyQuat)

  // Standard ray-sphere intersect.  L = center - origin; tCenter = L·D is
  // the parameter at the point on the ray closest to the sphere center,
  // d² = |L|² − tCenter² is its squared perp-distance.  Miss when d² > R².
  _surfL.copy(_surfBodyCenter).sub(ray.origin)
  const tCenter = _surfL.dot(ray.direction)
  const d2 = _surfL.lengthSq() - (tCenter * tCenter)
  const r2 = radius * radius
  if (d2 > r2) {
    return null
  }
  const dt = Math.sqrt(r2 - d2)
  const tNear = tCenter - dt
  const tFar = tCenter + dt
  // Pick the front-facing intersect when the camera is outside the sphere
  // (tNear > 0); if the camera is inside (tNear < 0 < tFar) we still want
  // a forward hit so the user can dblclick to land while already at low
  // altitude.  tFar < 0 means the entire sphere is behind the camera.
  const t = (tNear > 0) ? tNear : (tFar > 0 ? tFar : null)
  if (t === null) {
    return null
  }

  _surfHit.copy(ray.origin).addScaledVector(ray.direction, t)
  return worldToLatLngAlt(_surfHit, _surfBodyCenter, _surfBodyQuat, radius)
}
