import {Group, Vector3} from 'three'
import {assertFinite} from '@pablo-mayrgundter/testing.js/testing.js'
import SpriteSheet from './SpriteSheet.js'
import {point} from './shapes.js'
import {latLngAltToBodyFixed} from '../coords.js'
import {placeRank} from './labelDeclutter.js'
import {PLACE_LABELS, labelFont} from './labelStyle.js'
import {cellInView, groupByCell, horizonAngle} from './placeCells.js'
import {labelTextColor, overlay} from '../shared.js'


// Tier reveal thresholds: planet apparent DIAMETER as a fraction of
// viewport height.  Viewport-relative so the visual size at which each
// tier reveals stays consistent across 720p / 1080p / 4K / 8K monitors.
//
// The whole reveal sequence sits in the "planet fills most of the
// screen" regime — earlier tunings let T0 fire at fraction ≈ 0.06
// (planet a small disc), which made even the marquee names crowd the
// view long before the user was close enough to read them.  Now nothing
// reveals until the planet is ~3/4 of the screen height.
//
// T0 reveals at d ≈ 3.3 R, T1 at d ≈ 2.4 R, T2 at d ≈ 1.5 R, and T3 at
// d ≈ 1.2 R (a fraction of 1.8): the small craters, near the ground.  (At
// the default field of view a body in the camera's face is 2.0, so a
// fraction above that is reached only by zooming the lens.)
const DEFAULT_TIER_FRAC = [0.75, 1.0, 1.5, 1.8]

// The catalogue is fetched (#258) once the body is this large, ahead of tier
// 0's 0.75: at the default field about 12 radii from its centre, so a go to
// the body, arriving at 10, asks as it arrives, and the names are in well
// before the camera closes to 3.3, where the first of them show.
export const LOAD_FRAC = 0.2

// After a failed fetch the approach asks again no sooner than this.
export const LOAD_RETRY_MS = 30000

// Labels to a sheet.  A sheet is a square canvas of its labels, uploaded as
// one texture: a tier of 1,500 craters in one would be a texture of 4,000
// px a side.  Chunks of this many keep each a megapixel or so.
const SHEET_LABELS = 192

// From this tier on a tier's sheets are built by cell of the sphere
// (placeCells.js) as the camera comes to see them, not all at once: a body's
// smallest craters are a thousand or more labels, a texture of 13 MP for the
// Moon's, where from a height a tenth of the sphere is in view.
const CELL_FROM_TIER = 2

// Per-entry altitude (`a`, in m) is preserved as-is.  We don't add a fixed
// surface lift any more: the surface-visibility SpriteSheet shader uses
// depthTest=false plus a per-vertex back-hemisphere discard, so labels
// can't be clipped by sphere curvature even at the limb where the
// surface curves rapidly relative to the sprite's screen-space extent.
// Picking (Picker.queryPlaces) reads the same un-lifted body-fixed XYZ,
// so click zones land where the labels appear.


/**
 * Surface places (cities, craters, landing sites…) on a celestial body.
 *
 * Lives in the rotating Planet Object3D's local frame so labels inherit
 * axial tilt + sidereal rotation via the scene graph — entry positions are
 * raw body-fixed XYZ from latLngAltToBodyFixed, no per-frame transform work.
 *
 * LOD: per-tier SpriteSheets are lazy-instantiated the first time their
 * reveal threshold (planet diameter as fraction of viewport height) is
 * crossed.  Per-frame visibility toggling is driven by an invisible
 * placeholder Points whose onBeforeRender computes the apparent diameter
 * for the parent body.
 */
export default class Places extends Group {
  /**
   * @param {string} bodyName For node naming + debugging
   * @param {number} planetRadius Body radius in meters
   * @param {number[]} [tierThresholds] Override DEFAULT_TIER_FRAC.  Each
   *   entry is planet apparent diameter as a fraction of viewport height.
   * @param {Function} [load] A body's name to a Promise of its places
   *   (loadPlaces)
   */
  constructor(bodyName, planetRadius, tierThresholds = DEFAULT_TIER_FRAC, load = loadPlaces) {
    super()
    this.name = `${bodyName}.places`
    this.bodyName = bodyName
    this.planetRadius = assertFinite(planetRadius)
    this.tierThresholds = tierThresholds
    // The catalogue: 'idle' (not asked for), 'loading', 'loaded' or 'failed'.
    this.loadState = 'idle'
    this._load = load
    this._loading = null
    this._failedAt = 0
    this.entries = []
    this.byTier = []
    this.tierGroups = []
    this._planetWorldPos = new Vector3()
    this._camWorldPos = new Vector3()
    this._camLocal = new Vector3()
    this._installLODHook()
  }


  /**
   * Replace the catalog and bucket by tier.  Higher-tier sheets are not
   * built until their pixel threshold is first crossed (see _updateLOD).
   *
   * @param {Array<{n:string,t?:number,lat:number,lng:number,a?:number,k?:string}>} entries
   */
  setEntries(entries) {
    this.loadState = 'loaded'
    this._disposeTiers()
    this.entries = entries
    this.byTier = []
    for (const e of entries) {
      const t = e.t ?? 0
      if (!this.byTier[t]) {
        this.byTier[t] = []
      }
      this.byTier[t].push(e)
    }
  }


  /**
   * Fetch the catalogue (loadPlaces: once for the page) and take its places.
   * The camera approaching the body asks (the LOD hook, from LOAD_FRAC);
   * anything that needs them sooner can.  A failure is logged, and the next
   * call asks again; the LOD hook waits LOAD_RETRY_MS first.
   *
   * @returns {Promise<void>} Resolves when the places are in, or the fetch failed
   */
  ensureLoaded() {
    if (this.loadState === 'loaded') {
      return Promise.resolve()
    }
    if (this.loadState === 'loading') {
      return this._loading
    }
    this.loadState = 'loading'
    this._loading = this._load(this.bodyName).then((entries) => {
      this.setEntries(entries)
    }, (e) => {
      this.loadState = 'failed'
      this._failedAt = Date.now()
      console.warn(`Places: ${this.bodyName}'s catalogue didn't load:`, e?.message ?? e)
    })
    return this._loading
  }


  /**
   * Whether the LOD hook should ask for the catalogue now.
   *
   * @param {number} fraction The body's diameter over the viewport's height
   * @param {number} [now] ms
   * @returns {boolean}
   */
  wantsLoad(fraction, now = Date.now()) {
    if (fraction < LOAD_FRAC) {
      return false
    }
    return this.loadState === 'idle' || (this.loadState === 'failed' && now - this._failedAt >= LOAD_RETRY_MS)
  }


  /**
   * Compute the body's apparent radius in viewport pixels at the camera.
   * Kept for external use (tests, debugging) — internally
   * `diameterFraction` is what drives tier reveal.
   *
   * @param {object} camera Three.js PerspectiveCamera (uses .fov)
   * @param {number} viewportH Viewport height in pixels
   * @returns {number}
   */
  screenPx(camera, viewportH) {
    const parent = this.parent
    if (!parent) {
      return 0
    }
    parent.getWorldPosition(this._planetWorldPos)
    camera.getWorldPosition(this._camWorldPos)
    const camDist = this._camWorldPos.distanceTo(this._planetWorldPos)
    const r = this.planetRadius
    // Half-angle subtended by the body, valid even when camera is inside.
    const angRad = Math.atan2(r, Math.max(camDist, r))
    const halfFovRad = (camera.fov * Math.PI) / 360
    return (angRad / halfFovRad) * (viewportH / 2)
  }


  /**
   * Compute the body's apparent DIAMETER as a fraction of viewport height.
   * Viewport-relative so a single threshold reads the same on 1080p, 4K,
   * 8K, etc — the basis for tier reveal.
   *
   * @param {object} camera Three.js PerspectiveCamera (uses .fov)
   * @param {number} viewportH Viewport height in pixels
   * @returns {number} fraction (1.0 means body diameter equals screen height)
   */
  diameterFraction(camera, viewportH) {
    if (viewportH <= 0) {
      return 0
    }
    // screenPx is the apparent RADIUS in pixels; diameter / vph = 2*sp/vph.
    return (2 * this.screenPx(camera, viewportH)) / viewportH
  }


  /**
   * Visibility test for tier `t` at a given diameter fraction.  Exposed
   * for tests so we don't need a real renderer/camera to verify the LOD
   * logic.
   *
   * @param {number} t
   * @param {number} fraction body diameter / viewport height
   * @returns {boolean}
   */
  shouldShowTier(t, fraction) {
    const threshold = this.tierThresholds[t]
    if (threshold === undefined) {
      return false
    }
    return fraction >= threshold
  }


  /**
   * Build the label sheets for tier `t` from this.byTier[t]: a group of
   * chunks of SHEET_LABELS, each its own sheet (and its own pick targets).
   * A tier from CELL_FROM_TIER builds none yet: it groups its places by cell
   * of the sphere, and `_showCells` builds a cell's sheets when the camera
   * first sees its ground.
   */
  _buildTier(t) {
    const entries = this.byTier[t]
    if (!entries || entries.length === 0) {
      return
    }
    const tierGroup = new Group()
    tierGroup.name = `${this.bodyName}.places.t${t}`
    tierGroup.userData.tier = t
    if (t >= CELL_FROM_TIER) {
      tierGroup.userData.cells = groupByCell(entries)
    } else {
      this._addSheets(tierGroup, t, entries.map((e, rank) => ({e, rank})), entries.length)
    }
    tierGroup.visible = false // _updateLOD will turn on this same frame
    this.tierGroups[t] = tierGroup
    this.add(tierGroup)
  }


  /**
   * @param {Group} group To add the sheets to
   * @param {number} t The tier
   * @param {Array<{e: object, rank: number}>} items Places, each with its
   *   place in the tier
   * @param {number} tierCount How many places the tier has
   */
  _addSheets(group, t, items, tierCount) {
    for (let from = 0; from < items.length; from += SHEET_LABELS) {
      const chunk = items.slice(from, from + SHEET_LABELS)
      // Longest first, so the sheet's rows pack tightly (SpriteSheet.sideToPack).
      chunk.sort((a, b) => b.e.n.length - a.e.n.length)
      group.add(this._buildSheet(t, chunk, tierCount))
    }
  }


  /**
   * Show the cells of tier `t` the camera can see, building the sheets of
   * one the first time it can, and hide the rest (kept: a label sheet is
   * built once).
   *
   * @param {number} t A tier that groups by cell
   * @param {object} camera
   */
  _showCells(t, camera) {
    const group = this.tierGroups[t]
    const cells = group.userData.cells
    this._camLocal.setFromMatrixPosition(camera.matrixWorld)
    this.worldToLocal(this._camLocal)
    const dist = this._camLocal.length()
    const dir = dist > 0 ? this._camLocal.multiplyScalar(1 / dist) : this._camLocal.set(0, 1, 0)
    const cap = horizonAngle(dist, this.planetRadius)
    const count = this.byTier[t].length
    for (const cell of cells) {
      const inView = cellInView(cell, dir, cap)
      if (inView && !cell.group) {
        cell.group = new Group()
        cell.group.name = `${group.name}.cell`
        this._addSheets(cell.group, t, cell.items, count)
        group.add(cell.group)
      }
      if (cell.group) {
        cell.group.visible = inView
      }
    }
  }


  /**
   * @param {number} t The tier
   * @param {Array<{e: object, rank: number}>} chunk The entries, and their
   *   places in the tier, in the order they go on the sheet
   * @param {number} tierCount How many places the tier has
   * @returns {Group} The sheet's sprites and what a pick and the declutter need of it
   */
  _buildSheet(t, chunk, tierCount) {
    // surfaceVisibility=true: per-vertex back-hemisphere discard +
    // depthTest=false, so labels never get clipped by the curving sphere
    // at the limb (sprite pixels extending toward disc centre share the
    // anchor's depth but the surface there can be much closer to the
    // camera).  Non-RTE: positions are body-local (small magnitude),
    // three.js handles body-local → world via modelMatrix.
    // Sized by distance (labelStyle.js PLACE_LABELS).
    const sheet = new SpriteSheet(chunk.length, chunk.map(({e}) => e.n), labelFont(PLACE_LABELS), [0, 0], false, true,
        {scalable: true})
    for (const {e} of chunk) {
      const xyz = latLngAltToBodyFixed(e.lat, e.lng, e.a ?? 0, this.planetRadius)
      sheet.add(xyz.x, xyz.y, xyz.z, e.n, labelTextColor)
    }
    const points = overlay(sheet.compile())
    const g = new Group()
    g.name = `${this.bodyName}.places.t${t}.sheet`
    g.userData.tier = t
    g.userData.sheet = sheet
    // A click or tap on a label targets its place, a double click goes to it
    // (labelPick.js, Scene.onClick); the far side's are not hit.
    g.userData.labelTargets = chunk.map(({e}) => ({
      kind: 'place', body: this.bodyName, name: e.n, lat: e.lat, lng: e.lng, alt: e.a ?? undefined,
    }))
    g.userData.labelBody = this
    // Where two touch, the larger feature's name wins (labelDeclutter.js);
    // the catalogue lists a tier largest first.
    g.userData.declutter = true
    g.userData.labelRank = chunk.map(({rank}) => placeRank(t, rank, tierCount))
    // Sized and dimmed by distance among the places' names in view
    // (labelStyle.js styleLabels); still ranked by tier, the larger feature
    // first.
    g.userData.labelStyle = PLACE_LABELS
    g.userData.labelMeasure = (i, cam, at) => cam.distanceTo(at)
    g.add(points)
    return g
  }


  /** Install an invisible Points whose onBeforeRender drives per-frame LOD. */
  _installLODHook() {
    const placeholder = point({
      opacity: 0,
      depthTest: false,
      depthWrite: false,
      transparent: true,
    })
    placeholder.name = `${this.bodyName}.places.lodHook`
    // Hook runs only when the placeholder itself isn't culled.  It sits at
    // the parent's origin, so it's visible whenever the planet is in frame.
    placeholder.onBeforeRender = (renderer, _scene, camera) => {
      const frac = this.diameterFraction(camera, renderer.domElement.clientHeight)
      if (this.wantsLoad(frac)) {
        this.ensureLoaded()
      }
      for (let t = 0; t < this.tierThresholds.length; t++) {
        if (!this.byTier[t]) {
          continue
        }
        const want = this.shouldShowTier(t, frac)
        if (want && !this.tierGroups[t]) {
          this._buildTier(t)
        }
        if (this.tierGroups[t]) {
          this.tierGroups[t].visible = want
          if (want && this.tierGroups[t].userData.cells) {
            this._showCells(t, camera)
          }
        }
      }
    }
    this._lodHook = placeholder
    this.add(placeholder)
  }


  /** Free GPU resources for every built tier. */
  _disposeTiers() {
    for (const group of this.tierGroups) {
      if (!group) {
        continue
      }
      this.remove(group)
      group.traverse((node) => {
        if (node.isPoints) {
          node.geometry.dispose()
          node.material.uniforms?.map?.value?.dispose()
          node.material.dispose()
          node.userData.sheet?.canvas?.remove?.()
        }
      })
    }
    this.tierGroups = []
  }
}


const catalogues = new Map() // body name → Promise of its places


/**
 * A body's place catalogue (`data/places/<body>.json`), fetched once for the
 * page: the labels (Places), the search and a link to a place all share it,
 * and concurrent asks share the request.  A failure rejects, and isn't kept:
 * the next ask fetches it again.
 *
 * @param {string} bodyName
 * @param {Function} [fetchFn] fetch, or like it
 * @returns {Promise<Array>} The places
 */
export function loadPlaces(bodyName, fetchFn = (...args) => globalThis.fetch(...args)) {
  let p = catalogues.get(bodyName)
  if (!p) {
    p = (async () => {
      const rsp = await fetchFn(`data/places/${bodyName}.json`)
      if (!rsp?.ok) {
        throw new Error(`${rsp?.status ?? 'no response'}`)
      }
      const json = await rsp.json()
      return Array.isArray(json?.places) ? json.places : []
    })()
    catalogues.set(bodyName, p)
    p.catch(() => {
      if (catalogues.get(bodyName) === p) {
        catalogues.delete(bodyName)
      }
    })
  }
  return p
}


/**
 * A body's places, or [] if they can't be had (a missing catalogue, a
 * network or parse error), with a warning, so a missing catalog degrades
 * silently rather than blowing up the planet.
 *
 * @param {string} bodyName
 * @returns {Promise<Array>}
 */
export async function fetchPlaces(bodyName) {
  try {
    return await loadPlaces(bodyName)
  } catch (e) {
    console.warn(`Places: failed to load ${bodyName}.json`, e)
    return []
  }
}


/** Forget the catalogues fetched.  For tests. */
export function _resetPlaces() {
  catalogues.clear()
}
